def is_simple_power(x, n):
    if n == 1:
        return x == 1
    low, high = 0, int(x ** 0.5) + 1
    while low <= high:
        mid = (low + high) // 2
        power = n ** mid
        if power == x:
            return True
        elif power < x:
            low = mid + 1
        else:
            high = mid - 1
    return False
```

